<style>
.site-manager-page{--sm-card:linear-gradient(180deg,rgba(37,47,59,.94),rgba(32,40,51,.96));--sm-border:rgba(255,255,255,.09);--sm-text:var(--text-primary,#f8fafc);--sm-muted:var(--text-muted,#94a3b8);--sm-blue:#60a5fa;--sm-gold:#d4a017;color:var(--sm-text)}
body.theme-light .site-manager-page,body[data-theme="light"] .site-manager-page,html[data-theme="light"] .site-manager-page,[data-bs-theme="light"] .site-manager-page{--sm-card:linear-gradient(180deg,rgba(255,255,255,.98),rgba(247,249,252,.98));--sm-border:rgba(21,32,51,.10);--sm-text:#18212b;--sm-muted:#64748b;--sm-blue:#2563eb}
.sm-card{border:1px solid var(--sm-border);background:var(--sm-card);box-shadow:0 8px 20px rgba(0,0,0,.10);color:var(--sm-text)}
.sm-shell{display:grid;grid-template-columns:220px minmax(0,1fr);gap:1rem;align-items:start}.sm-nav{display:grid;gap:.5rem;align-content:start;align-self:start}.sm-nav a{display:flex;align-items:center;gap:.55rem;border:1px solid var(--sm-border);background:transparent;color:var(--sm-text);padding:.75rem .85rem;text-decoration:none}.sm-nav a:hover{border-color:rgba(212,160,23,.42);background:rgba(212,160,23,.08);text-decoration:none}.sm-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.sm-card{padding:1rem}.sm-stat{display:grid;grid-template-columns:42px minmax(0,1fr);gap:.8rem;align-items:center;min-height:92px}.sm-stat__icon{width:42px;height:42px;display:grid;place-items:center;border:1px solid rgba(212,160,23,.28);background:rgba(212,160,23,.12);color:var(--sm-gold);font-size:1rem}.sm-stat small{display:block;color:var(--sm-muted);font-size:.72rem;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.sm-stat strong{display:block;font-size:1.75rem;line-height:1.05;font-weight:950;color:var(--sm-text)}.sm-table-wrap{overflow:auto}.sm-table{width:100%;border-collapse:collapse;color:var(--sm-text)}.sm-table th,.sm-table td{padding:.8rem .75rem;border-bottom:1px solid var(--sm-border);vertical-align:middle}.sm-table th{text-transform:uppercase;font-size:.72rem;color:var(--sm-muted)}.sm-badge{display:inline-flex;border:1px solid rgba(148,163,184,.22);background:rgba(148,163,184,.12);color:var(--sm-muted);padding:.25rem .55rem;font-size:.75rem}.sm-score{font-weight:900;color:var(--score-color,#94a3b8)}.sm-form{display:grid;gap:1rem}.sm-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.sm-form-grid-full{grid-column:span 2}.sm-label{display:block;margin-bottom:.35rem;color:var(--sm-muted);font-size:.76rem;font-weight:800;text-transform:uppercase}.sm-input,.sm-select,.sm-textarea{width:100%;border:1px solid var(--sm-border);background:rgba(255,255,255,.035);color:var(--sm-text);padding:.72rem .82rem}.sm-checks{display:flex;gap:1rem;flex-wrap:wrap}.sm-checks label{display:inline-flex;gap:.45rem;align-items:center}.sm-site-title strong,.sm-site-title span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sm-site-title span{color:var(--sm-muted);font-size:.82rem}.sm-actions-row{display:flex;gap:.4rem;flex-wrap:wrap}.sm-pagespeed-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.sm-pagespeed-card{border:1px solid var(--sm-border);background:var(--sm-card);box-shadow:0 8px 20px rgba(0,0,0,.10);color:var(--sm-text);padding:1rem}.sm-pagespeed-scores{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.5rem}.sm-pagespeed-scores div{display:grid;gap:.2rem}.sm-pagespeed-scores strong{font-size:1.15rem}.sm-pagespeed-scores small{color:var(--sm-muted);font-size:.7rem}.sm-btn{display:inline-flex;align-items:center;justify-content:center;gap:.45rem;min-height:34px;border:1px solid rgba(96,165,250,.28);background:rgba(96,165,250,.12);color:#bfdbfe;padding:.45rem .7rem;text-decoration:none;font-weight:800}.sm-btn:hover{text-decoration:none}.sm-btn-success{border-color:rgba(34,197,94,.24);background:rgba(34,197,94,.12);color:#86efac}.sm-btn-warning{border-color:rgba(245,158,11,.24);background:rgba(245,158,11,.12);color:#fcd34d}.sm-btn-danger{border-color:rgba(239,68,68,.24);background:rgba(239,68,68,.12);color:#fca5a5}
.sm-logo-upload{display:grid;grid-template-columns:86px minmax(0,1fr);gap:1rem;align-items:center;border:1px solid var(--sm-border);background:rgba(255,255,255,.035);padding:.85rem}.sm-logo-upload__preview{width:86px;height:86px;display:grid;place-items:center;overflow:hidden;border:1px solid var(--sm-border);background:rgba(148,163,184,.10);color:var(--sm-gold);font-size:1.5rem}.sm-logo-upload__preview img{width:100%;height:100%;object-fit:contain;padding:.35rem}.sm-logo-upload__body{min-width:0;display:grid;gap:.45rem}.sm-logo-upload__body small,.sm-logo-upload__body a{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--sm-muted);font-size:.78rem;font-weight:750}.sm-logo-upload__body a{color:var(--sm-blue);text-decoration:none}
@media(max-width:1000px){.sm-shell{grid-template-columns:1fr}.sm-nav{grid-template-columns:repeat(3,minmax(0,1fr))}.sm-grid,.sm-pagespeed-scores{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.sm-nav,.sm-grid,.sm-form-grid,.sm-pagespeed-grid{grid-template-columns:1fr}.sm-form-grid-full{grid-column:auto}}
main{min-height:auto!important}#app:has(.site-manager-page .sm-site-preview),main:has(.site-manager-page .sm-site-preview),.app-shell:has(.site-manager-page .sm-site-preview),.app-main:has(.site-manager-page .sm-site-preview){min-height:auto!important}.sm-section-title{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem;flex-wrap:wrap;margin-bottom:1rem}.sm-section-title h5{margin:0;font-weight:900}.sm-section-title span{color:var(--sm-muted);font-size:.8rem;font-weight:800}.sm-site-overview{display:grid;grid-template-columns:minmax(0,2fr) minmax(180px,1fr) minmax(0,2fr);gap:1rem;align-items:stretch}.sm-site-summary{display:grid;place-items:center;text-align:center;gap:.55rem;min-width:0}.sm-site-summary strong{display:block;max-width:100%;font-size:1.05rem;font-weight:950;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sm-site-summary>span,.sm-site-summary__url{display:block;max-width:100%;color:var(--sm-muted);font-size:.82rem;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-decoration:none}.sm-site-summary__url:hover{color:var(--sm-gold);text-decoration:none}.sm-site-summary__badges{display:flex;justify-content:center;gap:.4rem;flex-wrap:wrap}.sm-psi-donut-wrap{min-width:0;display:grid;justify-items:center;gap:.45rem}.sm-psi-donut{width:58px;height:58px;display:grid;place-items:center;border-radius:50%;background:conic-gradient(var(--psi-color) var(--psi-percent),rgba(148,163,184,.20) 0);color:var(--sm-text);font-size:.78rem;font-weight:950;position:relative}.sm-psi-donut::before{content:"";position:absolute;inset:6px;border-radius:50%;background:var(--sm-card)}.sm-psi-donut span{position:relative;z-index:1}.sm-psi-donut-wrap small{color:var(--sm-muted);font-size:.68rem;font-weight:900;text-align:center;line-height:1.15}.sm-site-preview{width:100%;height:min(62vh,620px);min-height:360px;border:1px solid var(--sm-border);background:rgba(255,255,255,.035);overflow:hidden}.sm-site-preview iframe{width:100%;height:100%;border:0;background:#fff}.sm-preview-note{margin:.65rem 0 0;color:var(--sm-muted);font-size:.8rem;font-weight:700}@media(max-width:1100px){.sm-site-overview{grid-template-columns:1fr}.sm-site-summary{order:-1}}
</style>
